import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    t = int(next(iterator))

    results = []

    for _ in range(t):
        m = int(next(iterator))

        row1 = []
        for _ in range(m):
            row1.append(int(next(iterator)))

        row2 = []
        for _ in range(m):
            row2.append(int(next(iterator)))

        if m == 1:
            results.append("0")
            continue

        prefix_row1 = [0] * (m + 1)
        suffix_row1 = [0] * (m + 1)

        for i in range(m):
            prefix_row1[i+1] = prefix_row1[i] + row1[i]

        for i in range(m - 1, -1, -1):
            suffix_row1[i] = suffix_row1[i+1] + row1[i]

        prefix_row2 = [0] * (m + 1)
        suffix_row2 = [0] * (m + 1)

        for j in range(m):
            prefix_row2[j+1] = prefix_row2[j] + row2[j]

        for j in range(m - 1, -1, -1):
           uffix_row2[j] = suffix_row2[j+1] + row2[j]

        min_bob_score = float('inf')

        for k in range(m):
            alice_path_sum = prefix_row1[k+1] + suffix_row2[k]
            bob_options = [
                suffix_row1[k],
                prefix_row2[k+1],
                prefix_row1[k] + suffix_row2[k+1]
            ]
            max_bob_for_k = max(bob_options)

            if max_bob_for_k < min_bob_score:
                min_bob_score = max_bob_for_k

        results.append(str(min_bob_score))

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
